  ['中景鏡頭 (Medium Shot)', '3:4'], ['牛仔中景 (Cowboy Shot)', '2:3'], ['全身鏡頭 (Full Body Shot)', '2:3'],
  ['全無', '2:3'],
];

test('main MJ takes the approved framing ratio when F follows PAGE1 and PAGE1 has no ratio', () => {
